#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_output_contains_all_expected_types() {
        let out = generate_wire_bindings();
        for expected in [
            "ContentCategory",
            "CompletionWire",
            "WorkCardDto",
            "PageDto",
            "ProgressSaveRequest",
            "HistoryEntryDto",
            "SearchHistoryEntryDto",
            "SearchHistoryListRequest",
            "MarkerDto",
            "StorageLocationDto",
            "ScanCancelResultDto",
            "LibraryScanEvent",
            "HomeDto",
            "ShelfDto",
            "WorkDetailHeaderDto",
            "WorkGetRequest",
            "ResourceSummaryDto",
            "ComicPageManifestDto",
            "DownloadTaskDto",
            "DownloadCreateRequest",
            "DownloadMutationResultDto",
            "DownloadRevealResultDto",
            "CacheScopeDto",
            "CacheClearResultDto",
            "ErrorReportLevelDto",
            "ErrorReportPreviewDto",
            "ErrorReportPreviewRequest",
            "ErrorReportConfirmResultDto",
            "ErrorReportActionResultDto",
            "VideoScreenshotBeginResultDto",
            "VideoScreenshotChunkRequest",
            "VideoScreenshotStatusDto",
            "VideoScreenshotResultDto",
            "ReaderTocGetRequest",
            "TocItemDto",
            "ReaderTocResultDto",
            "ReaderSearchRequest",
            "ReaderSearchHitDto",
            "ReaderSearchResultDto",
            "ReaderSearchEventKind",
            "ReaderSearchEventData",
            "ReaderSearchEvent",
            "ReaderSearchCancelRequest",
            "ReaderSearchCancelResultDto",
            "SubtitleFormatDto",
            "SubtitleTrackDto",
            "PreferenceTargetDto",
            "PreferenceReadingPatchDto",
            "PreferenceComicPatchDto",
            "PreferenceReadingSettingsDto",
            "PreferenceComicSettingsDto",
            "PreferenceGetRequest",
            "PreferenceUpdateRequest",
            "PreferenceGetResult",
            "PreferenceUpdateResult",
        ] {
            assert!(out.contains(expected), "生成物缺少类型 {expected}");
        }
        assert!(
            !out.contains("import type"),
            "单文件生成不得含跨文件 import"
        );
        assert!(
            out.lines().all(|line| line == line.trim_end()),
            "checked-in wire.ts 不得含行尾空白"
        );
        assert!(out.contains("positionMs: number"), "u64 wire 必须是 number");
        assert!(
            out.contains("schemaVersion: 1"),
            "WorkDetailHeaderDto schemaVersion 必须是 literal 1"
        );
    }

    #[test]
    fn page_dto_uses_null_not_required_number() {
        let out = generate_wire_bindings();
        assert!(
            out.contains("total: number | null"),
            "PageDto.total 必须是 number | null"
        );
        assert!(
            out.contains("schemaVersion"),
            "PageDto 必须带 schemaVersion"
        );
    }

    #[test]
    fn download_management_request_exposes_only_task_id() {
        let value = serde_json::to_value(DownloadTaskActionRequest {
            task_id: "task-id".into(),
        })
        .unwrap();
        assert_eq!(value, serde_json::json!({ "taskId": "task-id" }));
    }
}
